component_data_script:
def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

rows = []
try:
	for line in read_rows(props.get("entries")):
		parts = [part.strip() for part in str(line).split("|")]
		if len(parts) >= 3:
			aud = norm(parts[0])
			item = parts[1]
			note = parts[2]
		else:
			aud = "both"
			item = parts[0]
			note = parts[1] if len(parts) > 1 else ""
		if not item:
			continue
		rows.append({"aud": aud, "tag": tag_of(aud), "item": item, "note": note})
except Exception:
	rows = []
component.rows = rows
